import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Security Model","description":"","frontmatter":{"title":"Security Model"},"headers":[],"relativePath":"concepts/security-model.md","filePath":"concepts/security-model.md"}'),s={name:"concepts/security-model.md"};function a(n,e,l,c,d,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ol><li><strong>Any secret that reaches the client is public.</strong> Therefore no provider key, in any form, is ever sent to the device.</li><li><strong>The client is untrusted.</strong> Model access, limits, and identity are all enforced in the gateway. The app can only <em>request</em>; the gateway <em>decides</em>.</li><li><strong>You can read the code.</strong> The gateway is open source and deployed into your own project — audit the exact code in your request path.</li><li><strong>We are not in your request path.</strong> No Wingport-operated server sees your traffic, keys, prompts, or users (unless you later opt into Wingport Cloud).</li></ol><h2 id="specifics" tabindex="-1">Specifics <a class="header-anchor" href="#specifics" aria-label="Permalink to &quot;Specifics&quot;">​</a></h2><ul><li>JWTs are verified with your project&#39;s signing secret; expired/invalid tokens are rejected before any processing.</li><li>Quota checks happen <strong>before</strong> provider calls — abusive traffic costs you rate-limit rejections, not tokens.</li><li><code>maxConcurrentStreamsPerUser</code> and <code>requestsPerMinute</code> bound key-farming attempts from a compromised account.</li><li>Prompts and responses are <strong>not stored</strong> by default. Metering records token <em>counts</em>, not content. (Opt-in prompt logging is a roadmap plugin, stored — like everything — in your own database.)</li><li>Generated tables ship with RLS enabled: users can read their own usage rows; only the service role writes.</li></ul><h2 id="responsible-disclosure" tabindex="-1">Responsible disclosure <a class="header-anchor" href="#responsible-disclosure" aria-label="Permalink to &quot;Responsible disclosure&quot;">​</a></h2><p>Security reports: security@wingport.dev. Please do not open public issues for vulnerabilities.</p><hr>',9)])])}const m=t(s,[["render",a]]);export{h as __pageData,m as default};
